const $=s=>document.querySelector(s), $$=s=>[...document.querySelectorAll(s)];
let ticketPrice=250;
const img=p=>'https://image.tmdb.org/t/p/w500'+p;
const movies=[
{title:'Dune: Part Two',genre:'Sci-Fi / Adventure',lang:'English',rating:'9.2',votes:'132.4K votes',tag:'IMAX • 2D',image:img('/1pdfLvkbY9ohJlCjQH2CZjjYVvJ.jpg'),description:'Paul Atreides unites with Chani and the Fremen on a journey of revenge, destiny and impossible choices.'},
{title:'Chhaava',genre:'Action / Historical / Drama',lang:'Hindi',rating:'9.3',votes:'248.8K votes',tag:'FAN FAVOURITE',image:img('/2jYxSYDjBqWnxONbr4XZpiDu4jA.jpg'),description:'An epic story of courage and sacrifice, bringing the legacy of Chhatrapati Sambhaji Maharaj to the big screen.'},
{title:'Interstellar',genre:'Sci-Fi / Adventure / Drama',lang:'English',rating:'9.3',votes:'185.2K votes',tag:'BACK IN IMAX',image:img('/gEU2QniE6E77NI6lCU6MxlNBvIx.jpg'),description:'A team of explorers travels beyond this galaxy to discover whether mankind has a future among the stars.'},
{title:'Pushpa 2: The Rule',genre:'Action / Thriller',lang:'Telugu',rating:'8.8',votes:'312.6K votes',tag:'BLOCKBUSTER',image:img('/ngBH685O5eLw5JJ2ylGAKRZko1M.jpg'),description:'Pushpa takes on powerful new rivals as his empire grows in this high energy action spectacle.'},
{title:'The Dark Knight',genre:'Action / Crime / Drama',lang:'English',rating:'9.5',votes:'208.3K votes',tag:'CULT CLASSIC',image:img('/qJ2tW6WMUDux911r6m7haRef0WH.jpg'),description:'Batman faces his greatest test when a criminal mastermind plunges Gotham into chaos.'},
{title:'Daman',genre:'Drama / Adventure',lang:'Odia',rating:'9.1',votes:'24.5K votes',tag:'ODIA CINEMA',image:'https://images.unsplash.com/photo-1448375240586-882707db888b?auto=format&fit=crop&w=500&q=85',description:'A young doctor travels to a remote village, finding purpose and courage along the way.'},
{title:'Oppenheimer',genre:'Drama / History',lang:'English',rating:'9.0',votes:'186.5K votes',tag:'IMAX',image:img('/ptpr0kGAckfQkJeJIt8st5dglvd.jpg'),description:'The story of J. Robert Oppenheimer and the moment that changed the world forever.'}];
const photos={concert:'photo-1459749411175-04bf5292ceea',comedy:'photo-1475721027785-f74eccf877e2',music:'photo-1506157786151-b8491531f063',run:'photo-1552674605-db6ffd4facb5'};
const photo=(id,w=700)=>`https://images.unsplash.com/${id}?auto=format&fit=crop&w=${w}&q=85`;
const events=[{title:'An evening of indie magic',type:'Events',venue:'Utkal Open Air Theatre',price:799,date:'SAT, 14 NOV',image:photo(photos.concert)}, {title:'The laugh factory • Stand-up special',type:'Plays',venue:'Bhubaneswar Comedy Club',price:499,date:'SUN, 15 NOV',image:photo(photos.comedy)}, {title:'Under the stars • Music festival',type:'Events',venue:'Janata Maidan, Bhubaneswar',price:1299,date:'SAT, 21 NOV',image:photo(photos.music)}, {title:'Run for the good times',type:'Sports',venue:'Kalinga Stadium',price:399,date:'SUN, 22 NOV',image:photo(photos.run)}];
let language='All',category='All',expanded=false,query='',selectedMovie=null,seats=[],bookingDate='Today',bookingTime='7:30 PM',cinema='INOX: BMC Bhawani Mall';
function escapeHtml(s){return String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]))}
function render(){let list=movies.filter(m=>(language==='All'||m.lang===language)&&m.title.toLowerCase().includes(query.toLowerCase()));const eventMode=['Events','Plays','Sports','Activities'].includes(category);$('#results-title').innerHTML=(eventMode?category+' to explore':category==='Stream'?'Your next movie night':'Recommended movies')+'<span class="small-orange">✦</span>';if(eventMode){$('#movie-grid').innerHTML=events.filter(e=>category==='Activities'||e.type===category).filter(e=>e.title.toLowerCase().includes(query.toLowerCase())).map(eventMarkup).join('');$('#languages').style.visibility='hidden'}else{$('#languages').style.visibility='visible';$('#movie-grid').innerHTML=(expanded?list:list.slice(0,5)).map(m=>`<button class="movie-card" data-movie="${movies.indexOf(m)}"><div class="poster"><img src="${m.image}" alt="${m.title} movie poster" loading="lazy"><span class="poster-tag">${m.tag}</span><span class="poster-title">${m.title.toUpperCase()}</span></div><h3>${m.title}</h3><p>${m.genre}</p><p>${m.lang} • UA</p><div class="card-bottom"><span><span class="orange">★</span> <strong>${m.rating}</strong> &nbsp; ${m.votes}</span><b>↗</b></div></button>`).join('')}$('#empty').hidden=$('#movie-grid').children.length>0;$('#see-all').textContent=expanded?'Show less ↗':'Explore all movies ↗'}
function eventMarkup(e){return `<button class="event-card" data-event="${events.indexOf(e)}"><div class="event-image"><img src="${e.image}" alt="${e.title}" loading="lazy"><span>${e.date}</span></div><h3>${e.title}</h3><p>${e.venue}</p><b>₹${e.price} onwards <span class="orange">↗</span></b></button>`}
$('#events-grid').innerHTML=events.map(eventMarkup).join('');
const cats=[['Live music','Feel every beat','♬','#e9e3d3'],['Comedy nights','A good kind of ache','☺','#eadedb'],['Sports & fitness','Get in the game','◎','#e0e7df'],['Theatre & arts','Stories come alive','❋','#e4e0ec'],['Experiences','Try a little different','⌁','#e6e8d9']];
$('#event-categories').innerHTML=cats.map((c,i)=>`<button class="event-category" data-event-category="${i}" style="background:${c[3]}"><span>${c[1]}</span><h3>${c[0]}</h3><i>${c[2]}</i></button>`).join('');
function toast(t){$('#toast').textContent=t;$('#toast').classList.add('show');clearTimeout(window.toastTimer);window.toastTimer=setTimeout(()=>$('#toast').classList.remove('show'),3500)}
function modal(html){$('#modal-content').innerHTML=html;if(!$('#modal').open)$('#modal').showModal()}
function setCategory(c){category=c;query='';$('#search').value='';$$('[data-category]').forEach(b=>b.classList.toggle('active',b.dataset.category===c));$$('[data-filter]').forEach(b=>b.classList.toggle('selected',b.dataset.filter===c));render();$('.movies-section').scrollIntoView({behavior:'smooth',block:'start'})}
function detail(index){selectedMovie=movies[index];seats=[];const m=selectedMovie;modal(`<img class="modal-poster" src="${m.image}" alt="${m.title}"><div class="overline">THE BIG SCREEN AWAITS</div><h2>${m.title}</h2><div class="modal-tags">★ ${m.rating}/10 • ${m.lang} • UA</div><p>${m.description}</p><div class="clear"></div><h3>Make it a movie night</h3><p>Choose your date and showtime. Demo availability.</p><div class="modal-options dates">${['Today','Tomorrow','Sun, 26'].map((x,i)=>`<button class="${i===0?'selected':''}" data-date="${x}">${x}</button>`).join('')}</div><select class="form-field" id="cinema"><option>INOX: BMC Bhawani Mall</option><option>Cinepolis: Esplanade One</option><option>PVR: Utkal Kanika Galleria</option></select><div class="modal-options times">${['10:30 AM','2:15 PM','7:30 PM','10:15 PM'].map(x=>`<button data-time="${x}" class="${x===bookingTime?'selected':''}">${x}</button>`).join('')}</div><button class="primary" id="choose-seats">Choose your seats ↗</button>`);bookingDate='Today'}
function seatView(){cinema=$('#cinema')?.value||cinema;modal(`<div class="overline">THE BEST SEAT IS YOURS</div><h2>${selectedMovie.title}</h2><p>${escapeHtml(cinema)}<br>${bookingDate} · ${bookingTime} · ${selectedMovie.lang}</p><div class="screen">SCREEN THIS WAY</div><div class="seat-grid">${Array.from({length:50},(_,i)=>{const name=String.fromCharCode(65+Math.floor(i/10))+(i%10+1);return `<button ${[3,4,13,21,22,37,48].includes(i)?'disabled':''} data-seat="${name}" aria-label="Seat ${name}">${name}</button>`}).join('')}</div><p>₹${ticketPrice} per seat · Select up to 8 seats · Grey seats are unavailable</p><div class="booking-total"><strong id="seat-total">Select your seats</strong><button class="primary" id="continue-booking">Continue ↗</button></div>`)}
function checkout(){if(!seats.length)return toast('Choose at least one seat to continue.');const total=seats.length*ticketPrice;modal(`<div class="overline">ONE LAST THING</div><h2>Your movie night, sorted.</h2><p><strong>${selectedMovie.title}</strong><br>${escapeHtml(cinema)}<br>${bookingDate} · ${bookingTime}<br>Seats: ${seats.join(', ')}</p><form id="checkout"><input class="form-field" type="email" id="booking-email" required placeholder="Email for your demo ticket" aria-label="Booking email"><div class="booking-total"><strong>Total ₹${total}<small style="display:block;font-weight:400;color:#888;font-size:10px">Demo booking · no payment collected</small></strong><button class="primary">Confirm demo booking ↗</button></div></form>`)}
function showBooking(b){modal(`<div class="ticket-success"><span>✳</span><div class="overline">YOU'VE GOT PLANS</div><h2>See you at the movies.</h2><p>Your demo booking is confirmed.</p><h3>${escapeHtml(b.title)}</h3><p>${escapeHtml(b.cinema)}<br>${escapeHtml(b.date)} · ${escapeHtml(b.time)}<br>Seats ${b.seats.map(escapeHtml).join(', ')}<br>₹${b.total} · ${escapeHtml(b.id)}</p><p>This is a demo ticket, not valid for cinema admission.</p><button class="primary" id="done">Back to discovering ↗</button></div>`)}
function action(a){if(a==='offers')modal('<div class="overline">ECHO PERKS</div><h2>Good plans. Better deals.</h2><p>Explore sample offers for your next night out.</p>'+[['FIRSTECHO','20% off your first booking','Up to ₹150 · New accounts'],['WEEKDAY','Buy 1, get 1 on Tuesdays','Selected cinemas · Up to ₹250'],['LIVEITUP','₹200 off live experiences','Minimum spend ₹1,499']].map(o=>`<div style="border:1px dashed #c9cbbf;padding:15px;margin:12px 0;border-radius:8px"><strong>${o[1]}</strong><p>${o[2]}</p><button class="text-link" data-copy="${o[0]}">${o[0]} · Copy code ↗</button></div>`).join(''));else if(a==='gift')modal('<div class="overline">GIVE A GREAT MEMORY</div><h2>A little joy, on you.</h2><p>Choose a gift card amount. Preview only; purchases are not connected.</p><div class="modal-options">'+[500,1000,2000,5000].map(n=>`<button data-gift="${n}">₹${n}</button>`).join('')+'</div><div id="gift-preview"></div>');else if(a==='list')modal('<div class="overline">TAKE THE STAGE</div><h2>Your show. Our spotlight.</h2><p>Tell us about the experience you want to host.</p><form id="partner"><input class="form-field" required placeholder="Your name" aria-label="Your name"><input class="form-field" type="email" required placeholder="Your email" aria-label="Your email"><input class="form-field" required placeholder="Event name" aria-label="Event name"><button class="primary">Save event enquiry ↗</button></form><p>This demo saves your enquiry on this device.</p>');else if(a==='bookings'){const b=JSON.parse(localStorage.getItem('orbitBookings')||'[]');modal('<h2>Your good times, lined up.</h2>'+ (b.length?b.map((x,i)=>`<button class="form-field" data-booking="${i}">${escapeHtml(x.title)} · ${escapeHtml(x.date)} · ${escapeHtml(x.id)} ↗</button>`).join(''):'<p>No bookings yet. Find a movie you love and book your seats.</p>'))}else if(a==='events'){setCategory('Events')}else modal('<h2>Here to help.</h2><p>Find your saved tickets under My bookings. Movie and event availability is sample data; this demo does not connect to cinemas or collect payments.</p><button class="primary" data-action="bookings">View my bookings ↗</button>')}
document.addEventListener('click',async e=>{const b=e.target.closest('button');if(!b)return;if(b.dataset.category)setCategory(b.dataset.category);if(b.dataset.filter)setCategory(b.dataset.filter);if(b.dataset.lang){language=b.dataset.lang;$$('[data-lang]').forEach(x=>x.classList.toggle('selected',x===b));render()}if(b.dataset.movie!==undefined)detail(+b.dataset.movie);if(b.dataset.event!==undefined){const x=events[+b.dataset.event];modal(`<img src="${x.image}" style="width:100%;height:210px;object-fit:cover;border-radius:9px" alt="${x.title}"><h2>${x.title}</h2><p>${x.date} · ${x.venue}</p><p>An unforgettable experience, right here in your city. Sample event listing.</p><strong>₹${x.price} onwards</strong><p><button class="primary" id="event-interest">Notify me about tickets ↗</button></p>`)}if(b.dataset.eventCategory!==undefined){const c=['Events','Plays','Sports','Plays','Activities'][+b.dataset.eventCategory];setCategory(c)}if(b.dataset.action)action(b.dataset.action);if(b.dataset.date){bookingDate=b.dataset.date;$$('[data-date]').forEach(x=>x.classList.toggle('selected',x===b))}if(b.dataset.time){bookingTime=b.dataset.time;$$('[data-time]').forEach(x=>x.classList.toggle('selected',x===b))}if(b.dataset.seat){const s=b.dataset.seat;if(seats.includes(s))seats=seats.filter(x=>x!==s);else if(seats.length<8)seats.push(s);else return toast('You can choose up to 8 seats.');b.classList.toggle('selected',seats.includes(s));$('#seat-total').textContent=seats.length?`${seats.length} seat${seats.length>1?'s':''} · ₹${seats.length*ticketPrice}`:'Select your seats'}if(b.id==='choose-seats')seatView();if(b.id==='continue-booking')checkout();if(b.classList.contains('modal-close')||b.id==='done')$('#modal').close();if(b.dataset.city){$('#city span').textContent=b.dataset.city;$$('.city-name').forEach(x=>x.textContent=b.dataset.city);localStorage.setItem('orbitCity',b.dataset.city);$('#modal').close();toast('Exploring '+b.dataset.city)}if(b.dataset.copy){try{await navigator.clipboard.writeText(b.dataset.copy);toast('Offer code copied')}catch{toast('Your code: '+b.dataset.copy)}}if(b.dataset.gift)$('#gift-preview').innerHTML=`<p>A ₹${b.dataset.gift} gift of great memories. Gift card checkout is coming soon.</p>`;if(b.dataset.booking!==undefined)showBooking(JSON.parse(localStorage.getItem('orbitBookings')||'[]')[+b.dataset.booking]);if(b.id==='event-interest'){toast('Interest saved on this device. No notification service is connected.');localStorage.setItem('orbitEventInterest','true');$('#modal').close()}});
$('#search').addEventListener('input',e=>{query=e.target.value;expanded=true;render()});$('#search').addEventListener('keydown',e=>{if(e.key==='Enter')$('.movies-section').scrollIntoView({behavior:'smooth'})});document.addEventListener('keydown',e=>{if((e.metaKey||e.ctrlKey)&&e.key==='k'){e.preventDefault();$('#search').focus()}});
$('#see-all').onclick=()=>{expanded=!expanded;render()};$('#hero-book').onclick=()=>detail(heroIndex===0?2:heroIndex===1?0:4);$('#stream-button').onclick=()=>setCategory('Stream');$('#city').onclick=()=>modal('<div class="overline">FIND YOUR ECHO</div><h2>Where are we heading out?</h2><p>Select your city</p><div class="modal-options">'+['Bhubaneswar','Mumbai','Delhi-NCR','Bengaluru','Hyderabad','Chennai','Pune','Kolkata','Cuttack'].map(c=>`<button data-city="${c}">⌖ ${c}</button>`).join('')+'</div>');$('#signin').onclick=()=>modal('<div class="overline">WELCOME TO YOUR ECHO</div><h2>Good times start here.</h2><p>Set up a local demo profile to personalise your experience.</p><form id="profile"><input class="form-field" required id="profile-name" placeholder="Your name" aria-label="Your name" maxlength="30"><input class="form-field" type="email" required placeholder="Email address" aria-label="Email address"><button class="primary">Continue ↗</button></form><p>No account is created on a server.</p>');
document.addEventListener('submit',e=>{e.preventDefault();if(e.target.id==='checkout'){const b={title:selectedMovie.title,cinema,date:bookingDate,time:bookingTime,seats:[...seats],total:seats.length*ticketPrice,id:'ORB-'+Date.now().toString(36).toUpperCase()};const bs=JSON.parse(localStorage.getItem('orbitBookings')||'[]');bs.unshift(b);localStorage.setItem('orbitBookings',JSON.stringify(bs));showBooking(b)}if(e.target.id==='profile'){const n=$('#profile-name').value.trim();if(!n)return;localStorage.setItem('orbitName',n);$('#signin').textContent=n;$('#modal').close();toast('Welcome to your echo, '+n)}if(e.target.id==='newsletter'){localStorage.setItem('orbitNewsletter',e.target.querySelector('input').value);e.target.reset();toast('Email saved locally. Newsletter delivery is not connected.')}if(e.target.id==='partner'){localStorage.setItem('orbitPartner',JSON.stringify([...e.target.querySelectorAll('input')].map(x=>x.value)));$('#modal').close();toast('Your event enquiry is saved on this device.')}});
let heroIndex=0;const features=[['INTERSTELLAR','Christopher Nolan’s',photo('photo-1446776811953-b23d57bd21aa',2000)],['DUNE: PART TWO','Denis Villeneuve’s',photo('photo-1509316785289-025f5b846b35',2000)],['THE DARK KNIGHT','Christopher Nolan’s',photo('photo-1478720568477-152d9b164e26',2000)]];function changeHero(dir){heroIndex=(heroIndex+dir+3)%3;const f=features[heroIndex];$('.hero h1').textContent=f[0];$('.hero-kicker').textContent=f[1];$('.hero-image').style.backgroundImage=`url('${f[2]}')`;$('.hero-bottom>span').innerHTML=`0${heroIndex+1} <span class="slash">/ 03</span>`;$('.progress').innerHTML=features.map((_,i)=>i===heroIndex?'<b></b>':'<i></i>').join('')}$('#hero-next').onclick=()=>changeHero(1);$('#hero-prev').onclick=()=>changeHero(-1);$('#trailer').onclick=()=>modal(`<div class="overline">OFFICIAL TRAILER</div><h2>${features[heroIndex][0]}</h2><p>Watch the trailer on YouTube in a new tab.</p><a class="primary" style="display:inline-block" target="_blank" rel="noopener noreferrer" href="https://www.youtube.com/watch?v=${['zSWdZVtXT7E','Way9Dexny3w','EXeTwQWrcwY'][heroIndex]}">Open trailer ↗</a>`);
$('#modal').addEventListener('click',e=>{if(e.target===$('#modal')){const r=$('#modal').getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)$('#modal').close()}});const savedCity=localStorage.getItem('orbitCity');if(savedCity){$('#city span').textContent=savedCity;$$('.city-name').forEach(x=>x.textContent=savedCity)}const name=localStorage.getItem('orbitName');if(name)$('#signin').textContent=name;render();

